import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

instance_norm_divide_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void instance_norm_divide_kernel(
    const float* input, float* output,
    int N, int C, int H, int W,
    float eps, float divide_by) {

    int n = blockIdx.x;
    int c = blockIdx.y;
    int num_elements = H * W;

    extern __shared__ float sdata[];
    float* sum_ptr = sdata;
    float* sum_sq_ptr = &sdata[blockDim.x];

    int tid = threadIdx.x;
    float sum = 0.0f;
    float sum_sq = 0.0f;

    for (int i = tid; i < num_elements; i += blockDim.x) {
        int h = i / W;
        int w = i % W;
        int idx = ((n * C + c) * H + h) * W + w;
        float val = input[idx];
        sum += val;
        sum_sq += val * val;
    }

    sum_ptr[tid] = sum;
    sum_sq_ptr[tid] = sum_sq;
    __syncthreads();

    for (int s = blockDim.x/2; s>0; s>>=1) {
        if (tid < s) {
            sum_ptr[tid] += sum_ptr[tid + s];
            sum_sq_ptr[tid] += sum_sq_ptr[tid + s];
        }
        __syncthreads();
    }

    float total_sum = sum_ptr[0];
    float total_sum_sq = sum_sq_ptr[0];
    float mean = total_sum / num_elements;
    float variance = (total_sum_sq / num_elements) - (mean * mean);
    variance = fmaxf(variance, 0.0f) + eps;
    float inv_std = rsqrtf(variance);
    float scale = inv_std / divide_by;

    for (int i = tid; i < num_elements; i += blockDim.x) {
        int h = i / W;
        int w = i % W;
        int idx = ((n * C + c) * H + h) * W + w;
        float val = (input[idx] - mean) * scale;
        output[idx] = val;
    }
}

torch::Tensor instance_norm_divide_cuda(torch::Tensor input, float eps, float divide_by) {
    input = input.contiguous();
    auto N = input.size(0);
    auto C = input.size(1);
    auto H = input.size(2);
    auto W = input.size(3);
    auto output = torch::empty_like(input);

    dim3 grid(N, C);
    int block_size = 256;
    size_t shared_size = 2 * block_size * sizeof(float);

    instance_norm_divide_kernel<<<grid, block_size, shared_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, H, W,
        eps, divide_by
    );

    return output;
}
"""

instance_norm_divide_cpp_source = "torch::Tensor instance_norm_divide_cuda(torch::Tensor input, float eps, float divide_by);"

instance_norm_divide = load_inline(
    name='instance_norm_divide',
    cpp_sources=instance_norm_divide_cpp_source,
    cuda_sources=instance_norm_divide_source,
    functions=['instance_norm_divide_cuda'],
    verbose=True,
    extra_cflags=['-O3'],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, divide_by):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.divide_by = divide_by
        self.eps = 1e-5
        self.instance_norm_divide = instance_norm_divide

    def forward(self, x):
        x = self.conv(x)
        x = self.instance_norm_divide.instance_norm_divide_cuda(x, self.eps, self.divide_by)
        return x
